# Draw both views from identical hole coordinates, mirroring only the underside.
Add-Type -AssemblyName System.Drawing
$bmp = [System.Drawing.Bitmap]::new(1700,1150)
$g = [System.Drawing.Graphics]::FromImage($bmp)
$g.SmoothingMode = 'AntiAlias'
$g.Clear([System.Drawing.Color]::White)
function Label($s,$x,$y,$size=20,$color='#18212b') {
  $font = [System.Drawing.Font]::new('Arial',$size)
  $brush = [System.Drawing.SolidBrush]::new([System.Drawing.ColorTranslator]::FromHtml($color))
  $g.DrawString($s,$font,$brush,[single]$x,[single]$y)
  $font.Dispose(); $brush.Dispose()
}
function Point($hole,$side) {
  $row = [int][char]$hole.Substring(0,1) - [int][char]'A'
  $col = [int]$hole.Substring(1)
  if ($side -eq 0) { $x = 85+($col-1)*58 } else { $x = 925+(12-$col)*58 }
  return [System.Drawing.PointF]::new($x,(220+$row*48))
}
function Wire($holes,$side,$color,$width=5) {
  $pen = [System.Drawing.Pen]::new([System.Drawing.ColorTranslator]::FromHtml($color),$width)
  $pts = [System.Drawing.PointF[]]@($holes | ForEach-Object { Point $_ $side })
  $g.DrawLines($pen,$pts)
  foreach ($hole in @($holes[0],$holes[-1])) {
    $p = Point $hole $side
    $brush = [System.Drawing.SolidBrush]::new($pen.Color)
    $g.FillEllipse($brush,($p.X-6),($p.Y-6),12,12)
    $brush.Dispose()
  }
  $pen.Dispose()
}
Label 'BC-250 sense interface: isolated-pad perfboard' 45 22 30
Label 'Local 12-column x 10-row grid. Mark A1 yourself; these are NOT the board printed coordinates.' 45 76 19
Label 'Use one area of your larger board. Every pad is isolated: install every listed wire.' 45 108 19
Label 'COMPONENT SIDE' 65 158 23
Label 'SOLDER SIDE: flipped left-to-right' 905 158 23
foreach ($side in 0,1) {
  for ($c=1; $c -le 12; $c++) {
    $p = Point "A$c" $side
    Label "$c" ($p.X-10) 192 14
    for ($r=0; $r -lt 10; $r++) {
      $h = "$([char](65+$r))$c"
      $p = Point $h $side
      $g.DrawEllipse([System.Drawing.Pens]::Gray,($p.X-6),($p.Y-6),12,12)
    }
  }
  for ($r=0; $r -lt 10; $r++) {
    Label "$([char](65+$r))" (45+$side*840) (207+$r*48) 16
  }
  $p = Point 'A1' $side
  $g.DrawEllipse([System.Drawing.Pens]::Red,($p.X-12),($p.Y-12),24,24)
}
# Components on top only; small rectangles are resistor bodies, not copper tracks.
foreach ($res in @(@('B4','E4','R2 10k'),@('B7','E7','R1 33k'),@('H7','H11','R3 100k'))) {
  Wire @($res[0],$res[1]) 0 '#785321' 3
  $a=Point $res[0] 0; $b=Point $res[1] 0
  $cx=($a.X+$b.X)/2; $cy=($a.Y+$b.Y)/2
  if ($a.X -eq $b.X) { $w=24; $h=74 } else { $w=94; $h=24 }
  $g.FillRectangle([System.Drawing.Brushes]::Wheat,($cx-$w/2),($cy-$h/2),$w,$h)
  $g.DrawRectangle([System.Drawing.Pens]::Black,($cx-$w/2),($cy-$h/2),$w,$h)
  if ($a.X -eq $b.X) { Label $res[2] ($cx+18) ($cy-15) 16 }
  else { Label $res[2] ($cx-45) ($cy+24) 16 }
}
foreach ($side in 0,1) {
  foreach ($item in @(@('F6','C'),@('F7','B'),@('F8','E'))) {
    $p=Point $item[0] $side
    $g.FillEllipse([System.Drawing.Brushes]::Black,($p.X-7),($p.Y-7),14,14)
    Label $item[1] ($p.X-8) ($p.Y-30) 17
  }
}
Label 'Q1: BC547B' 80 508 17
Label 'C=F6, B=F7, E=F8' 80 540 16
# Insulated point-to-point wires on underside. Intermediate bends are NOT solder joints.
$nets = @(
  @('B2,B4','#d13b36'),
  @('B11,B7','#21814a'),
  @('E7,F7,H7','#ac6410'),
  @('E4,F4,F6','#2765bc'),
  @('F6,D6,D2','#2765bc'),
  @('F8,F11,H11,J11,J2','#18212b')
)
foreach ($net in $nets) { Wire ($net[0].Split(',')) 1 $net[1] }
foreach ($joint in @(@('F7','#ac6410'),@('H11','#18212b'))) {
  $p=Point $joint[0] 1
  $brush=[System.Drawing.SolidBrush]::new([System.Drawing.ColorTranslator]::FromHtml($joint[1]))
  $g.FillEllipse($brush,($p.X-7),($p.Y-7),14,14)
  $brush.Dispose()
}
foreach ($side in 0,1) {
  foreach ($item in @(@('B2','3V3','#d13b36'),@('B11','SENSE','#21814a'),@('D2','GPIO4','#2765bc'),@('J2','GND','#18212b'))) {
    $p=Point $item[0] $side
    Label $item[1] ($p.X-25) ($p.Y+12) 14 $item[2]
  }
}
